    initial_positions = list(map(int, data[1:4]))
    matrix = [data[4 + i * n:4 + (i + 1) * n] for i in range(n)]

    return n, initial_positions, matrix

def bfs(n, initial_positions, matrix):
    from collections import deque

    start_state = tuple(sorted(initial_positions))
    queue = deque([(start_state, [])])
    visited = set([start_state])

    while queue:
        current_state, path = queue.popleft()

        if current_state == (1, 2, 3):
            return path

